sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float amount;
uniform float softness;
uniform float invert;
uniform float method;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0 || (method < 0.5 && blur <= 0.0)) return src;
    float b = float(blurred.eval(coord).a);
    float keep = method > 0.5 ? b : smoothstep(amount - softness * 0.5, amount + softness * 0.5, b);
    return src * half(invert > 0.5 ? 1.0 - keep : keep);
}
